/* Academic extension. Catalog entries and offerings are deliberately separate. */
function validateAcademic(data){
 const fail=()=>{throw Error('Dados acadêmicos inválidos. Nenhum registro foi substituído.')};
 const text=(v,n=300)=>typeof v==='string'&&v.length<=n;
 const list=v=>Array.isArray(v)&&v.length<=3000;
 if(!data||!Array.isArray(data.exams))return;
 if(data.si!==undefined){const p=data.si;if(!p||!['current','all'].includes(p.scope)||!['quiet','hidden'].includes(p.mascot)||!list(p.progress)||p.progress.some(x=>!text(x.key)||!['pending','completed','equivalent','planned'].includes(x.status)))fail()}
 for(const e of data.exams){const a=e.academic;if(a===undefined)continue;
  if(!a||!['semester','free'].includes(a.kind)||!text(a.term,30)||!Number.isInteger(a.period)||a.period<1||a.period>20||!['2017','2024','manual'].includes(a.matrix)||typeof a.archived!=='boolean'||!text(a.goal,1000)||!list(a.assessments)||!list(a.lessons)||!list(a.projects)||!list(a.activities)||!list(a.routines))fail();
  const ids=new Set(),sid=new Set(e.subjects.map(s=>s.id));const identity=x=>{if(!text(x.id)||!x.id||ids.has(x.id))fail();ids.add(x.id)};const ref=x=>{if(x.subjectId&&!sid.has(x.subjectId))fail()};const date=x=>typeof x==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x)&&Number.isFinite(Date.parse(x+'T12:00:00Z'));
  for(const s of e.subjects){const o=s.offering;if(o!==undefined&&(!o||!text(o.catalogKey)||!Number.isInteger(o.period)||o.period<1||o.period>20||!text(o.teacher,120)||!text(o.group,80)||!text(o.room,80)||!['enrolled','completed','pending','withdrawn'].includes(o.status)||!Number.isInteger(o.absences)||o.absences<0||o.absences>10000||!(o.absenceLimit===null||Number.isInteger(o.absenceLimit)&&o.absenceLimit>=0&&o.absenceLimit<=10000)))fail()}
  for(const x of a.assessments){identity(x);ref(x);if(!text(x.title,200)||!date(x.date)||!Number.isFinite(x.weight)||x.weight<=0||x.weight>1000||!(x.grade===null||Number.isFinite(x.grade)&&x.grade>=0&&x.grade<=10)||!['Prova','Trabalho','Projeto','Lista','Apresentação','Outro'].includes(x.kind))fail()}
  for(const x of a.lessons){identity(x);ref(x);if(!text(x.title,200)||!Number.isInteger(x.day)||x.day<0||x.day>6||!/^([01]\d|2[0-3]):[0-5]\d$/.test(x.start)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(x.end)||x.start>=x.end||!text(x.room,80))fail()}
  for(const x of a.projects){identity(x);ref(x);if(!text(x.title,200)||!date(x.date)||!text(x.url,10000)||x.url&&!/^https?:\/\//.test(x.url)||!text(x.notes,20000)||!list(x.tasks)||x.tasks.some(t=>!text(t.id)||!text(t.title,250)||typeof t.done!=='boolean'))fail()}
  for(const x of a.activities){identity(x);if(!text(x.title,200)||!date(x.date)||!text(x.category,120)||!Number.isFinite(x.hours)||x.hours<0||x.hours>10000||!Number.isFinite(x.validated)||x.validated<0||x.validated>x.hours||!text(x.evidence,10000)||x.evidence&&!/^https?:\/\//.test(x.evidence))fail()}
  for(const x of a.routines){identity(x);ref(x);if(!text(x.title,200)||!Number.isInteger(x.day)||x.day<0||x.day>6||!Number.isInteger(x.minutes)||x.minutes<5||x.minutes>240||!/^([01]\d|2[0-3]):[0-5]\d$/.test(x.start)||x.lastApplied!==null&&!date(x.lastApplied))fail()}
 }
}
const siNewAcademic=(kind,term='',period=1,matrix='manual')=>({kind,term,period,matrix,archived:false,goal:'',assessments:[],lessons:[],projects:[],activities:[],routines:[]});
const siOffering=(catalogKey='',period=1)=>({catalogKey,period,teacher:'',group:'',room:'',status:'enrolled',absences:0,absenceLimit:null});
